<!DOCTYPE html>
<html>
<head>
  <title>Sorting Algorithm Visualizer</title>
  <style>
    body {
      background-color: #1e1e1e;
      color: #d4d4d4;
      font-family: sans-serif;
    }

    #container {
      width: 80%;
      margin: 20px auto;
    }

    #bars {
      display: flex;
      height: 300px;
      border: 1px solid #555;
    }

    .bar {
      background-color: steelblue;
      width: 40px;
      margin: 0 5px;
      box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3);
      transition: height 0.3s ease; /* Smooth animation */
    }

    button {
      background-color: #3498db;
      color: white;
      border: none;
      padding: 10px 20px;
      margin: 10px;
      cursor: pointer;
      transition: background-color 0.3s ease; /* Smooth animation */
    }

    button:hover {
      background-color: #2980b9;
    }
  </style>
</head>
<body>
  <div id="container">
    <h1>Sorting Algorithm Visualizer</h1>
    <div id="bars"></div>
    <div>
      <button id="sort">Sort</button>
      <button id="shuffle">Shuffle</button>
      <button id="reset">Reset</button>
    </div>
  </div>

  <script>
    const arrayLength = 10;
    let arr = Array.from({ length: arrayLength }, () => Math.floor(Math.random() * 100));
    const barsDiv = document.getElementById('bars');
    const sortButton = document.getElementById('sort');
    const shuffleButton = document.getElementById('shuffle');
    const resetButton = document.getElementById('reset');

    function createBars() {
      for (let i = 0; i < arr.length; i++) {
        const bar = document.createElement('div');
        bar.classList.add('bar');
        bar.style.height = `${arr[i]}px`;
        barsDiv.appendChild(bar);
      }
    }

    function sortStep() {
      if (isSorted()) {
        return true;
      }

      // Simple bubble sort for demonstration purposes.  Replace with your chosen algorithm.
      for (let i = 0; i < arr.length - 1; i++) {
        for (let j = 0; j < arr.length - i - 1; j++) {
          if (arr[j] > arr[j + 1]) {
            // Swap elements
            const temp = arr[j];
            arr[j] = arr[j + 1];
            arr[j + 1] = temp;

            // Update bar heights
            const barJ = document.querySelector(`.bar:nth-child(${j + 1})`);
            const barJPlus1 = document.querySelector(`.bar:nth-child(${j + 2})`);
            barJ.style.height = `${arr[j]}px`;
            barJPlus1.style.height = `${arr[j+1]}px`;

          }
        }
      }
      return false;
    }

    function isSorted() {
      for (let i = 0; i < arr.length - 1; i++) {
        if (arr[i] > arr[i + 1]) {
          return false;
        }
      }
      return true;
    }

    function shuffleArray() {
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
       createBars(); // Redraw the bars after shuffling
    }

    function resetArray() {
      arr = Array.from({ length: arrayLength }, () => Math.floor(Math.random() * 100));
      createBars(); // Redraw the bars after resetting
    }


    window.viz = {
      array: function() { return arr; },
      setArray: function(a) { arr = a; createBars(); },
      sortStep: sortStep,
      sorted: function() { return isSorted(); }
    };

    createBars();

    shuffleButton.addEventListener('click', shuffleArray);
    sortButton.addEventListener('click', sortStep);
    resetButton.addEventListener('click', resetArray);
  </script>
</body>
</html>
